public void init()
{
    next init();

    if (GUPGlobalEnableFeatureHelper::useAttributeBasedPricing()
        && this.args().caller()
        && this.args().caller().name() == formStr(TAMRebateDeal))
    {
        FormRun callerForm = this.args().caller() as FormRun;
        TAMRebateDeal rebateDeal = callerForm.dataSource(formDataSourceStr(TAMRebateDeal, TAMRebateDeal)).cursor();
        // Check if the rebate deal is a GUP customer rebate
        if (GUPRebateMatchingHelper::isGUPCustomerRebate(rebateDeal))
        {
            Fund.visible(true);
            FreeItemSalesId.visible(true);
        }
    }
}
